:"sprinkler_gruppe","label":"Sprinklergruppe (Tab. 7/8/9)","type":"enum","required":true,"options":["t7","t8","t9"],"option_labels":{"t7":"Tab. 7 — Regnerkanone / Endkanone / Sprinkler > 2 m Wurfweite","t8":"Tab. 8 — ohne Endkanone / Düsenwagen / Sprinkler ≤ 2 m Wurfweite","t9":"Tab. 9 — urbane Überkopfbewässerung, nicht steuerbarer Zugang"},"visible_when":"technik IN {''beregnung_sprinkler'', ''mikrosprueh''}"},{"key":"wurfweite_m","label":"Wurfweite (ohne Wind)","type":"number","unit":"m","required":true,"min":0,"visible_when":"technik IN {''beregnung_sprinkler'', ''mikrosprueh''}","aria_label":"reguläre Wurfweite ohne Windeinflüsse"},{"key":"spritzschutz","label":"Spritzschutz (≥ 2 m Höhe, ≥ 1 m Stärke)","type":"boolean","visible_when":"technik IN {''beregnung_sprinkler'', ''mikrosprueh''}"},{"key":"steuerbarer_zugang","label":"steuerbarer Zugang (Abstandsregelung entfällt)","type":"boolean","visible_when":"sprinkler_gruppe == ''t9''"},{"key":"faktor","label":"Faktor (× Wurfweite)","type":"derived","expr":"if(steuerbarer_zugang == true, 0, lookup(''TAB789'', sprinkler_gruppe, if(gueteklasse == ''D'', ''d'', ''a_c''), if(spritzschutz == true, ''mit'', ''ohne''), ''faktor''))","display":"badge","value_labels":{"0":"entfällt (steuerbarer Zugang)","1":"1-fache Wurfweite","2":"2-fache Wurfweite","3":"3-fache Wurfweite"}},{"key":"min_abstand_m","label":"Mindestabstand","type":"derived","expr":"faktor * wurfweite_m"},{"key":"abstand_ist_m","label":"Abstand vorhanden","type":"number","unit":"m","required":true,"min":0,"visible_when":"technik IN {''beregnung_sprinkler'', ''mikrosprueh''}","aria_label":"vorhandener Abstand vom Wasseraustritt"},{"key":"abstand_ok","label":"Abstand ≥ Mindestabstand","type":"derived","expr":"if(technik IN {''beregnung_sprinkler'', ''mikrosprueh''}, if(faktor == 0, 1, if(abstand_ist_m >= min_abstand_m, 1, 0)), 1)","display":"badge","value_labels":{"0":"unterschritten","1":"eingehalten"}},{"key":"weidegang_laktierend","label":"Weidegang durch laktierendes Vieh","type":"boolean"},{"key":"laktierend_konflikt","label":"laktierend","type":"derived","expr":"if(weidegang_laktierend == true AND gueteklasse IN {''C-1'', ''C-2''}, 1, 0)","display":"badge","value_labels":{"0":"","1":"Güteklasse C: Beweidung durch laktierendes Vieh grundsätzlich ausgeschlossen"}}],"footer":["flaeche_gesamt_ha","abstand_verletzungen"],"note":"Eine konkrete Beurteilung und Festlegung von Mindestabständen sowie eines gegebenenfalls zu steuernden Zugangs muss im RMP erfolgen."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
