SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = '08-B'), 'wasseranalysen', 'Wasseranalysen (Datum, Parameter, Messwert → Einhaltung des Tab.-11-Toleranzwerts)', 'json', NULL, false, '§5.6.2, Tab. 11', 'Plan 3: Zeilen je Analyse; Toleranzwert je Zeile aus TAB11 (die (*)-Parameter nach dem vererbten pflanzentyp, L1369; pH als Bereich; die (*)-Werte als Obergrenzen gelesen, m1200_3-J-3); Verstöße → analysen_verletzungen (M12003-08-D1); die 17 Skalare k_konz … zn_konz und CR-05 bleiben (m1200_3-G-5); Schwermetall-Fracht aus Konzentration × Menge nicht kodiert (m1200_3-F-1).', 'imported_unverified', '7 Tabelle 11: Toleranzbereiche für chemische und sonstige Parameter im Bewässerungswasser — (*) salzempfindliche/salzunempfindliche Pflanzen. — Für bewässerte salzempfindliche Kulturen, wie zum Beispiel im Gartenbau kultiviert, wird empfohlen, zu erwartende und zu tolerierende Frachten und Konzentrationen fallspezifisch zu ermitteln. Dabei können sowohl Erfahrungswerte der Züchter und Anbauer als auch Tabellenwerke und andere relevante Publikationen, unter anderem TGL 6466/01 (1977, 1986), berücksichtigt werden, die über die Angaben der Tabelle 11 hinausgehen.', 'register', '{"title":"Wasseranalysen (Tab. 11)","subtitle":"§5.6.2 — je Probe Datum, Parameter und Messwert; Toleranzwert je Zeile aus Tab. 11 (Chlorid / Wasserhärte / Leitfähigkeit nach Pflanzentyp, pH als Bereich 5,0–9,5)","add_label":"+ Analyse","placement":"section","columns":[{"key":"date","label":"Datum","type":"date","required":true},{"key":"parameter","label":"Parameter","type":"enum","required":true,"options":["kalium","natrium","chlorid","sulfat","nitrat","ph","wasserhaerte","leitfaehigkeit","blei","cadmium","chrom","eisen","kupfer","mangan","nickel","quecksilber","zink"],"option_labels":{"kalium":"Kalium (mg/l)","natrium":"Natrium (mg/l)","chlorid":"Chlorid (mg/l)","sulfat":"Sulfat (mg/l)","nitrat":"Nitrat (mg/l)","ph":"pH-Wert (pH)","wasserhaerte":"Wasserhärte (°dH)","leitfaehigkeit":"Leitfähigkeit (µS/cm)","blei":"Blei (µg/l)","cadmium":"Cadmium (µg/l)","chrom":"Chrom (µg/l)","eisen":"Eisen (µg/l)","kupfer":"Kupfer (µg/l)","mangan":"Mangan (µg/l)","nickel":"Nickel (µg/l)","quecksilber":"Quecksilber (µg/l)","zink":"Zink (µg/l)"},"discriminator":true},{"key":"wert","label":"Messwert","type":"number","required":true,"min":0,"aria_label":"Messwert der Probe"},{"key":"einheit","label":"Einheit","type":"derived","expr":"lookup(''TAB11'', parameter, ''unit'')"},{"key":"limit_se","label":"Toleranz salzempfindlich","type":"derived","expr":"lookup(''TAB11'', parameter, ''limit_salzempfindlich'')"},{"key":"limit_su","label":"Toleranz salzunempfindlich","type":"derived","expr":"lookup(''TAB11'', parameter, ''limit_salzunempfindlich'')"},{"key":"limit","label":"Toleranzwert (Tab. 11)","type":"derived","expr":"if(parameter IN {''chlorid'', ''wasserhaerte'', ''leitfaehigkeit''}, if(pflanzentyp == ''salzempfindlich'', limit_se, limit_su), limit_se)"},{"key":"ph_min","label":"pH min","type":"derived","expr":"lookup(''TAB11'', parameter, ''ph_min'')"},{"key":"ph_max","label":"pH max","type":"derived","expr":"lookup(''TAB11'', parameter, ''ph_max'')"},{"key":"ok","label":"eingehalten","type":"derived","expr":"if(parameter == ''ph'', if(wert >= ph_min AND wert <= ph_max, 1, 0), if(wert <= limit, 1, 0))","display":"badge","value_labels":{"0":"überschritten","1":"eingehalten"}}],"footer":["analysen_verletzungen"],"note":"Für bewässerte salzempfindliche Kulturen, wie zum Beispiel im Gartenbau kultiviert, wird empfohlen, zu erwartende und zu tolerierende Frachten und Konzentrationen fallspezifisch zu ermitteln. Dabei können sowohl Erfahrungswerte der Züchter und Anbauer als auch Tabellenwerke und andere relevante Publikationen, unter anderem TGL 6466/01 (1977, 1986), berücksichtigt werden, die über die Angaben der Tabelle 11 hinausgehen."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'wasseranalysen') AND w.code = 'M12003-08' AND s.code = 'DWA-M-1200-3';
