SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = '10-B'), 'speicher_1200_3', 'Speicher und Behälter (Typ → Speichersystem nach Tab. 3, Volumen, O2-Sättigung, Verweilzeit)', 'json', NULL, false, '§5.1.1, Tab. 3; §7.2.4', 'Plan 3: Zeilen je Speicher; Speichersystem je Zeile aus TAB3_MAP (prod-Token → geschlossen/offen/transport — der CR-06-Fix, m1200_3-G-1), zulässige Klassen aus TAB3 gegen die vererbte gueteklasse (Konsumenten-Ergänzung M12003-01 → -10 STAGED, m1200_3-C-7; bis dahin bleibt das Badge leer); ab 72 h Verweilzeit Belüftung / Umwälzung (L1626 / L1633); O2 ≥ 50 % (L1622); Σ Volumen → speichervolumen_ist_m3 (M12003-10-D3); der Skalar speichertyp bleibt (CR-06 / -06-2 STAGED, m1200_3-G-1).', 'imported_unverified', 'Für die Speicherung von Bewässerungswasser werden in Abhängigkeit von der Güteklasse des aufbereiteten Wassers Speichertypen entsprechend Tabelle 3 empfohlen. — \hline Geschlossene Speicher & A, B \\ — \hline Offene Speicher & C, D \\ — \hline Transportbehälter & Nach Bedarf \\ — Die Sauerstoffsättigung des aufbereiteten Wassers sollte in allen Speichersystemen 50 \% relative Sättigung während der Speicherung nicht unterschreiten. — \section*{Offene Speicher}

Ab 72 h Verweilzeit des aufbereiteten Wassers im System werden folgende Maßnahmen vorgeschlagen:
I Belüftung,
I regelmäßige Umwälzung des Wasserkörpers.', 'register', '{"title":"Speicher und Behälter","subtitle":"§5.1.1 / Tab. 3 / §7.2.4 — je Speicher Typ, Volumen, Sauerstoffsättigung (≥ 50 %), Verweilzeit (ab 72 h Belüftung + Umwälzung)","add_label":"+ Speicher","placement":"section","columns":[{"key":"label","label":"Bezeichnung","type":"text","required":true},{"key":"speichertyp","label":"Speichertyp","type":"enum","required":true,"options":["offen_ortsfest_kurz","offen_ortsfest_lang","geschlossen_ortsfest_kurz","geschlossen_ortsfest_lang","transportbehaelter"],"option_labels":{"offen_ortsfest_kurz":"offener ortsfester Speicher — kurz- bis mittelfristig","offen_ortsfest_lang":"offener ortsfester Speicher — langfristig","geschlossen_ortsfest_kurz":"geschlossener ortsfester Speicher — kurz- bis mittelfristig","geschlossen_ortsfest_lang":"geschlossener ortsfester Speicher — langfristig","transportbehaelter":"Transportbehälter"},"discriminator":true},{"key":"speichersystem","label":"Speichersystem (Tab. 3)","type":"derived","expr":"lookup(''TAB3_MAP'', speichertyp, ''system'')","value_labels":{"geschlossen":"geschlossen","offen":"offen","transport":"Transportbehälter"}},{"key":"klassen_zulaessig","label":"Zulässige Güteklassen (Tab. 3)","type":"derived","expr":"lookup(''TAB3'', speichersystem, ''klassen_zulaessig'')"},{"key":"klasse_ok","label":"Güteklasse zulässig","type":"derived","expr":"if(gueteklasse == ''A'', if(lookup(''TAB3'', speichersystem, ''allows_a'') == true, 1, 0), if(gueteklasse IN {''B-1'', ''B-2''}, if(lookup(''TAB3'', speichersystem, ''allows_b'') == true, 1, 0), if(gueteklasse IN {''C-1'', ''C-2''}, if(lookup(''TAB3'', speichersystem, ''allows_c'') == true, 1, 0), if(lookup(''TAB3'', speichersystem, ''allows_d'') == true, 1, 0))))","display":"badge","value_labels":{"0":"Güteklasse nicht für dieses Speichersystem empfohlen (Tab. 3)","1":"Güteklasse für dieses Speichersystem empfohlen (Tab. 3)"}},{"key":"volumen_m3","label":"Volumen","type":"number","unit":"m³","required":true,"min":0,"aria_label":"Speichervolumen"},{"key":"o2_saettigung_pct","label":"Sauerstoffsättigung","type":"number","unit":"%","min":0,"max":100,"aria_label":"relative Sauerstoffsättigung während der Speicherung"},{"key":"o2_ok","label":"O2 ≥ 50 %","type":"derived","expr":"if(o2_saettigung_pct >= 50, 1, 0)","display":"badge","value_labels":{"0":"unter 50 % relative Sättigung (§7.2.4)","1":""}},{"key":"verweilzeit_h","label":"Verweilzeit","type":"number","unit":"h","min":0,"aria_label":"Verweilzeit des aufbereiteten Wassers im System"},{"key":"belueftung","label":"Belüftung (ab 72 h)","type":"boolean","visible_when":"verweilzeit_h >= 72"},{"key":"umwaelzung","label":"regelmäßige Umwälzung (ab 72 h)","type":"boolean","visible_when":"verweilzeit_h >= 72"}],"footer":["speichervolumen_ist_m3"],"note":"Die Sauerstoffsättigung des aufbereiteten Wassers sollte in allen Speichersystemen 50 \\% relative Sättigung während der Speicherung nicht unterschreiten."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'speicher_1200_3') AND w.code = 'M12003-10' AND s.code = 'DWA-M-1200-3';
