SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = '10-D'), 'bewaesserungshoehe_tab5', 'Normgröße Bewässerungshöhe nach Tab. 5 (Beispiel: 20 mm)', 'number', 'mm', false, '§5.2.1, Tab. 5', 'Plan 3: Ausgabe der Gleichung M12003-10-D2 (lookup S_TAB5_BEISPIEL, bewaesserungshoehe_mm — Orientierungswert L790; skalare Gleichung, nicht materialisiert); Vorbelegung des Eingabefelds bewaesserungshoehe ist Entscheidung des Planers.', 'imported_unverified', 'Für die Dimensionierungen von Speichern ist das Beispiel der Tabelle 5 als Orientierung dienlich. — \hline & Zu bewässernde Fläche & 10 ha \\
