\hline \multicolumn{2}{|l|}{Dauer einer Befüllung} & 100 h \\
\hline & entspricht & $4,2 \mathrm{~d}$ \\', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'bewaesserungshoehe_tab5') AND w.code = 'M12003-10' AND s.code = 'DWA-M-1200-3';
