SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = '10-D'), 'speichervolumen_calc', 'Minimal erforderliches Speichervolumen aus Σ Schlagfläche × Bewässerungshöhe (Tab. 5)', 'number', 'm³', false, '§5.2.1, Tab. 5', 'Plan 3: Ausgabe der Gleichung M12003-10-D1 (bewaesserungshoehe × flaeche_gesamt_ha × 10 — die gedruckte Tab.-5-Arithmetik 20 mm × 10 ha = 2000 m³, Faktor 10 = mm·ha → m³); liest flaeche_gesamt_ha von M12003-06 erst nach der Konsumenten-Ergänzung (m1200_3-C-7); Ablösung von Gl-Helper-1 (flaeche_groesse) STAGED (m1200_3-R-1).', 'imported_unverified', 'Für die Dimensionierungen von Speichern ist das Beispiel der Tabelle 5 als Orientierung dienlich. — \hline & Zu bewässernde Fläche & 10 ha \\
\hline & Normgröße Bewässerungshöhe & 20 mm \\
