FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'speichervolumen_calc') AND w.code = 'M12003-10' AND s.code = 'DWA-M-1200-3';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = '11-B'), 'druckleitungen', 'Druckleitungsabschnitte (Leitungstyp, Länge, Arbeitsdruck → Kosten und Energiebedarf nach Tab. 6)', 'json', NULL, false, '§5.2.2, Tab. 6; §5.1.6', 'Plan 3: Zeilen je Abschnitt; Material / Einbau (lookup_value) und kWh p. a. je gewähltem Arbeitsdruck aus TAB6 (anhaltswert — schematischer Überblick, Stand Q3/2022), linear auf die Länge skaliert (Tab. 6 gilt "pro 1.000 m Länge" — Skalierung ist Text-Ableitung, m1200_3-F-2); Σ → energie_kwh_a (M12003-11-D1) / leitungskosten_eur (M12003-11-D2); Volumenverlust ≤ 1 % je Abschnitt (L755); die Skalare leitungstyp / arbeitsdruck / volumenverlust_pct und CR-17-2 bleiben.', 'imported_unverified', '\caption{Tabelle 6: Schematischer Überblick zu Installations- und Energiekosten von Druckleitungen pro 1.000 m Länge (Stand Q3/2022, Beispiel ländlicher Raum Berlin-Brandenburg)} — 1) gilt für folgende Annahmen: Leitungslänge 1.000 m ohne Bögen, 0 m Höhenunterschied in der Druckleitung, $50 \mathrm{~m}^{3} / \mathrm{h}$ Fördervolumenstrom Pumpe, Saughöhe Pumpe 0 m , Gesamtwirkungsgrad Pumpe und Motor 0,75, 200 h Betriebszeit bei $5 \times 20 \mathrm{~mm}$ Bewässerungsgabe pro Jahr. — Durch die Erstabnahme vor Inbetriebnahme wird die Dichtheit festgestellt. Die Dichtheit ist durch hierfür geeignete Methoden festzustellen. Der Volumenverlust während des Transports durch Druckleitungen sollte $1 \%$ des Volumens nicht überschreiten. Der Verlust in Gerinnen sollte durch hierfür geeignete Maßnahmen auf ein Minimum reduziert werden (unvermeidliche Verluste).', 'register', '{"title":"Druckleitungsabschnitte (Tab. 6)","subtitle":"§5.2.2 — je Abschnitt Leitungstyp, Länge, Arbeitsdruck am Leitungsende; Kosten und Energiebedarf aus Tab. 6 (je 1.000 m, Annahmen Anm. 1) auf die Länge skaliert","add_label":"+ Abschnitt","placement":"section","columns":[{"key":"leitungstyp","label":"Leitungstyp (Tab. 6)","type":"lookup_key","required":true,"lookup":{"table_code":"TAB6"}},{"key":"laenge_m","label":"Länge","type":"number","unit":"m","required":true,"min":0,"aria_label":"Leitungslänge des Abschnitts"},{"key":"arbeitsdruck","label":"Arbeitsdruck am Leitungsende","type":"enum","required":true,"options":["2","4","6"],"option_labels":{"2":"2 bar","4":"4 bar","6":"6 bar"}},{"key":"material","label":"Materialkosten je 1.000 m (€)","type":"lookup_value","lookup":{"table_code":"TAB6","key_column":"leitungstyp","value":"material_eur"}},{"key":"einbau","label":"Einbaukosten je 1.000 m (€)","type":"lookup_value","lookup":{"table_code":"TAB6","key_column":"leitungstyp","value":"einbau_eur"}},{"key":"kwh","label":"Energiebedarf je 1.000 m (kWh p. a.)","type":"derived","expr":"if(arbeitsdruck == ''2'', lookup(''TAB6'', leitungstyp, ''kwh_2bar''), if(arbeitsdruck == ''4'', lookup(''TAB6'', leitungstyp, ''kwh_4bar''), lookup(''TAB6'', leitungstyp, ''kwh_6bar'')))"},{"key":"kwh_abschnitt","label":"Energiebedarf Abschnitt (kWh p. a.)","type":"derived","expr":"kwh * laenge_m / 1000"},{"key":"kosten_abschnitt_eur","label":"Material + Einbau Abschnitt (€)","type":"derived","expr":"(material + einbau) * laenge_m / 1000"},{"key":"volumenverlust_pct","label":"Volumenverlust","type":"number","unit":"%","min":0,"aria_label":"Volumenverlust des Abschnitts in Prozent"},{"key":"verlust_ok","label":"Verlust ≤ 1 %","type":"derived","expr":"if(volumenverlust_pct <= 1, 1, 0)","display":"badge","value_labels":{"0":"über 1 % des Volumens (§5.1.6)","1":""}}],"footer":["energie_kwh_a","leitungskosten_eur"],"note":"1) gilt für folgende Annahmen: Leitungslänge 1.000 m ohne Bögen, 0 m Höhenunterschied in der Druckleitung, $50 \\mathrm{~m}^{3} / \\mathrm{h}$ Fördervolumenstrom Pumpe, Saughöhe Pumpe 0 m , Gesamtwirkungsgrad Pumpe und Motor 0,75, 200 h Betriebszeit bei $5 \\times 20 \\mathrm{~mm}$ Bewässerungsgabe pro Jahr."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'druckleitungen') AND w.code = 'M12003-11' AND s.code = 'DWA-M-1200-3';
