SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = '12-B'), 'farbcode_hex_tab4', 'Hex-Farbcode der gewählten Kennzeichnungsfarbe (Tab. 4: 522C #BA9CC5 · 512C #833177)', 'text', NULL, false, '§5.1.4, Tab. 4', 'Plan 3: Wert aus TAB4 zur gewählten kennzeichnung_farbe (locked — "sind die Farben … als Hintergrund zu nutzen", L720); für vergleichbar_violett druckt Tab. 4 keine Zeile (ausgeblendet).', 'imported_unverified', 'Für Hinweise und Hinweisschilder textlicher Art sind die Farben „Pantone Purple 522C“, „Pantone Purple 512C" oder ein vergleichbarer violetter Farbton als Hintergrund zu nutzen (siehe Tabelle 4). — \hline Pantone Purple 522C & & \#CC99CC & 186, 156, 197 & 17, 37, 0, 0 & \#BA9CC5 \\ — \hline Pantone Purple 512C & & \#663366 & 131,49,119 & 0,63, 9, 49 & \#833177 \\', 'lookup_fill', '{"source_label":"Tab. 4"}'::jsonb, '{"table_code":"TAB4","role":"value","keys":[{"column":"farbe","from_symbol":"kennzeichnung_farbe"}],"value":"hex"}'::jsonb, 'kennzeichnung_farbe IN {''pantone_purple_522c'', ''pantone_purple_512c''}', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'farbcode_hex_tab4') AND w.code = 'M12003-12' AND s.code = 'DWA-M-1200-3';
UPDATE fields f SET widget = 'register', ui_config = '{"title":"Bewässerungstagebuch","subtitle":"§4.2 · Tab. 2 — je Bewässerungsgabe eine Zeile (schlagbezogen); Start/Ende wie gedruckt mit Uhrzeit","add_label":"+ Bewässerungsgabe","placement":"bottom","columns":[{"key":"start","label":"Start der Bewässerung","type":"text","required":true,"placeholder":"TT.MM.JJJJ hh:mm"},{"key":"ende","label":"Ende der Bewässerung","type":"text","placeholder":"TT.MM.JJJJ hh:mm"},{"key":"empfehlung_mm","label":"Empfehlung Bewässerungsgabe","type":"number","unit":"mm","min":0},{"key":"real_mm","label":"reale Bewässerungsgabe","type":"number","unit":"mm","required":true,"min":0},{"key":"flaeche_ha","label":"real bewässerte Fläche","type":"number","unit":"ha","required":true,"min":0},{"key":"wasser_m3","label":"Wasserverbrauch total","type":"number","unit":"m³","required":true,"min":0},{"key":"aufbereitet_m3","label":"Davon aufbereitetes Wasser","type":"number","unit":"m³","min":0},{"key":"kommentar","label":"Kommentar","type":"text"}],"footer":["wasserverbrauch_ist_m3"],"note":"Die Bewässerung landwirtschaftlicher und gartenbaulicher Kulturen ist in einem Bewässerungstagebuch schlagbezogen zu dokumentieren (Tabelle 2). Bei der Bewässerung nicht landwirtschaftlicher Flächen ist eine betrieblich und inhaltlich geeignete Form der Dokumentation zu erstellen."}'::jsonb, lookup = NULL, visible_when = NULL FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND f.symbol = 'bewaesserungstagebuch' AND w.code = 'M12003-18' AND s.code = 'DWA-M-1200-3' AND f.active;
