SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = '22-B'), 'chlorung_stoss_konz_tab14', 'Chlorung — Stoßkonzentration — Tab. 14 (30 mg/l)', 'number', 'mg/l', false, '§7.3.2, Tab. 14', 'Plan 3: Wert aus TAB14 zur gewählten desinfektion_methode (anhaltswert — "Empfohlene Konzentration gemäß ISO 16075-3:2021"); nur bei desinfektion_methode = chlorung sichtbar; Ablösung des bestehenden chlorung_stoss_konz STAGED (m1200_3-E-1).', 'imported_unverified', '\hline Chlorung & $30 \mathrm{mg} / \mathrm{l}$ & 12 h bis 24 h \\ — Mögliche Desinfektionsmaßnahmen für Tropf- und Mikrobewässerungssysteme sind in Tabelle 14 aufgeführt. Die Maßnahmen der Tabelle 14 dürfen nicht gleichzeitig ausgeführt werden. Nach Abschluss der Desinfektion ist das gesamte Bewässerungssystem zu spülen. Gegebenenfalls sind Rei-nigungs- und Desinfektionsdurchgänge zu wiederholen.', 'lookup_fill', '{"source_label":"Tab. 14 (ISO 16075-3:2021)"}'::jsonb, '{"table_code":"TAB14","role":"value","keys":[{"column":"methode","from_symbol":"desinfektion_methode"}],"value":"konzentration"}'::jsonb, 'desinfektion_methode == ''chlorung''', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'chlorung_stoss_konz_tab14') AND w.code = 'M12003-22' AND s.code = 'DWA-M-1200-3';
