SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = '22-B'), 'h2o2_stoss_konz_tab14', 'Wasserstoffperoxid — Stoßkonzentration — Tab. 14 (0,1 ml/l bzw. 1 l pro 10 m³)', 'number', 'ml/l', false, '§7.3.2, Tab. 14', 'Plan 3: Wert aus TAB14 zur gewählten desinfektion_methode (anhaltswert — "Empfohlene Konzentration gemäß ISO 16075-3:2021"); nur bei desinfektion_methode = h2o2 sichtbar; Ablösung des bestehenden h2o2_stoss_konz STAGED (m1200_3-E-1).', 'imported_unverified', '\hline Wasserstoffperoxid-Anwendung & $0,1 \mathrm{ml} / \mathrm{l}$ bzw. 1 l pro $10 \mathrm{~m}^{3}$ & 12 h bis 24 h \\ — Mögliche Desinfektionsmaßnahmen für Tropf- und Mikrobewässerungssysteme sind in Tabelle 14 aufgeführt. Die Maßnahmen der Tabelle 14 dürfen nicht gleichzeitig ausgeführt werden. Nach Abschluss der Desinfektion ist das gesamte Bewässerungssystem zu spülen. Gegebenenfalls sind Rei-nigungs- und Desinfektionsdurchgänge zu wiederholen.', 'lookup_fill', '{"source_label":"Tab. 14 (ISO 16075-3:2021)"}'::jsonb, '{"table_code":"TAB14","role":"value","keys":[{"column":"methode","from_symbol":"desinfektion_methode"}],"value":"konzentration"}'::jsonb, 'desinfektion_methode == ''h2o2''', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'h2o2_stoss_konz_tab14') AND w.code = 'M12003-22' AND s.code = 'DWA-M-1200-3';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = '22-B'), 'verweilzeit_min_tab14', 'Mindestverweilzeit im Bewässerungssystem — Tab. 14 (12 h bis 24 h)', 'number', 'h', false, '§7.3.2, Tab. 14', 'Plan 3: Wert aus TAB14 zur gewählten desinfektion_methode (anhaltswert — "Empfohlene Konzentration gemäß ISO 16075-3:2021"); untere Grenze des gedruckten Bereichs "12 h bis 24 h" (SR-2: die Verweilzeit selbst bleibt Eingabe in desinfektionen).', 'imported_unverified', '\hline Chlorung & $30 \mathrm{mg} / \mathrm{l}$ & 12 h bis 24 h \\ — \hline Wasserstoffperoxid-Anwendung & $0,1 \mathrm{ml} / \mathrm{l}$ bzw. 1 l pro $10 \mathrm{~m}^{3}$ & 12 h bis 24 h \\ — Mögliche Desinfektionsmaßnahmen für Tropf- und Mikrobewässerungssysteme sind in Tabelle 14 aufgeführt. Die Maßnahmen der Tabelle 14 dürfen nicht gleichzeitig ausgeführt werden. Nach Abschluss der Desinfektion ist das gesamte Bewässerungssystem zu spülen. Gegebenenfalls sind Rei-nigungs- und Desinfektionsdurchgänge zu wiederholen.', 'lookup_fill', '{"source_label":"Tab. 14 (ISO 16075-3:2021)"}'::jsonb, '{"table_code":"TAB14","role":"value","keys":[{"column":"methode","from_symbol":"desinfektion_methode"}],"value":"verweilzeit_min_h"}'::jsonb, 'desinfektion_methode IN {''chlorung'', ''h2o2''}', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'verweilzeit_min_tab14') AND w.code = 'M12003-22' AND s.code = 'DWA-M-1200-3';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = '22-B'), 'desinfektionen', 'Reinigungs- und Desinfektionsmaßnahmen (Methode, Speichersystem, Anwendungsmoment, Konzentration, Verweilzeit)', 'json', NULL, false, '§7.2.3, Tab. 13; §7.3.2, Tab. 14; §7.2.5', 'Plan 3: Zeilen je Maßnahme; Zulässigkeit je Zeile aus TAB13 (locked; UF / UV bei Befüllung / Speicherung nur mit Umwälzung, Anm. 4 — m1200_3-U-2); empfohlene Konzentration und Mindestverweilzeit aus TAB14 (anhaltswert) — thermisch ≥ 70 °C über 3 min (L1664, CR-16); die Skalare desinfektion_methode / desinfektion_konzentration / chlorung_stoss_konz / h2o2_stoss_konz und CR-16 bleiben (m1200_3-E-1 / -C-5).', 'imported_unverified', 'In Abhängigkeit von der baulichen und betrieblichen Situation können sich mikrobiologische Parameter des aufbereiteten Wassers während der Speicherung verändern. Mögliche Maßnahmen zur Desinfektion von Bewässerungswasser in Speichern sind in Tabelle 13 aufgeführt. Diese sind auch für das angeschlossene Leitungsnetz anzuwenden, da separate Vorgaben hier nicht existieren. — \caption{Tabelle 13: Mögliche und zulässige Maßnahmen zur Desinfektion von aufbereitetem Wasser aus und in Speichersystemen in Anlehnung an ISO 16075-3:2021} — Mögliche Desinfektionsmaßnahmen für Tropf- und Mikrobewässerungssysteme sind in Tabelle 14 aufgeführt. Die Maßnahmen der Tabelle 14 dürfen nicht gleichzeitig ausgeführt werden. Nach Abschluss der Desinfektion ist das gesamte Bewässerungssystem zu spülen. Gegebenenfalls sind Rei-nigungs- und Desinfektionsdurchgänge zu wiederholen. — Eine Anlagendesinfektion (Speicher und Leitungen) kann analog zum Trinkwasserbereich ebenfalls chemisch oder thermisch erfolgen; für letztere müssen die verbauten Materialien Temperaturen von $70^{\circ} \mathrm{C}$ über 3 min aushalten können, um die Mikroorganismen abzutöten bzw. zu inaktivieren.', 'register', '{"title":"Reinigungs- und Desinfektionsmaßnahmen","subtitle":"§7.2.3 Tab. 13 (Speicher: Methode × Speichersystem × Anwendungsmoment) / §7.3.2 Tab. 14 (Anlagendesinfektion als Stoßapplikation: Konzentration, Mindestverweilzeit) / §7.2.5 (thermisch ≥ 70 °C, 3 min)","add_label":"+ Maßnahme","placement":"section","columns":[{"key":"date","label":"Datum","type":"date","required":true},{"key":"methode","label":"Methode","type":"enum","required":true,"options":["chlorung","ozonung","pes","ultrafiltration","uv","h2o2","thermisch"],"option_labels":{"chlorung":"Chlorung","ozonung":"Ozonung","pes":"Peressigsäure (PES)","ultrafiltration":"Ultrafiltration","uv":"UV-Bestrahlung","h2o2":"Wasserstoffperoxid (H2O2)","thermisch":"thermisch (≥ 70 °C, ≥ 3 min)"},"discriminator":true},{"key":"speichersystem","label":"Speichersystem (Tab. 13)","type":"enum","options":["geschlossen","offen"],"option_labels":{"geschlossen":"geschlossen","offen":"offen"},"visible_when":"methode != ''thermisch''"},{"key":"moment","label":"Anwendungsmoment (Tab. 13)","type":"enum","options":["befuellung","speicherung","start","transport"],"option_labels":{"befuellung":"während der Befüllung","speicherung":"während der Speicherung","start":"mit Start der Bewässerung","transport":"Befüllen von Transportbehältern"},"visible_when":"methode != ''thermisch''"},{"key":"zulaessig","label":"zulässig (Tab. 13)","type":"derived","expr":"if(if(moment == ''befuellung'', lookup(''TAB13'', methode, speichersystem, ''befuellung''), if(moment == ''speicherung'', lookup(''TAB13'', methode, speichersystem, ''speicherung''), if(moment == ''start'', lookup(''TAB13'', methode, speichersystem, ''start''), lookup(''TAB13'', methode, speichersystem, ''transport'')))) == true, 1, 0)","display":"badge","value_labels":{"0":"nicht zulässig (Tab. 13)","1":"zulässig (Tab. 13)"}},{"key":"umwaelzung_hinweis","label":"Anm. 4","type":"derived","expr":"if(moment IN {''befuellung'', ''speicherung''} AND lookup(''TAB13'', methode, speichersystem, ''umwaelzung_bedingung'') == true, 1, 0)","display":"badge","value_labels":{"0":"","1":"nur unter der Voraussetzung einer Wasserumwälzung (Tab. 13 Anm. 4)"}},{"key":"konz_empf","label":"Empfohlene Konzentration (Tab. 14)","type":"derived","expr":"lookup(''TAB14'', methode, ''konz_text'')"},{"key":"konz_ist","label":"Angewandte Konzentration","type":"number","min":0,"aria_label":"angewandte Konzentration"},{"key":"konz_einheit","label":"Einheit","type":"derived","expr":"lookup(''TAB14'', methode, ''konz_unit'')"},{"key":"verweilzeit_h","label":"Verweilzeit im System","type":"number","unit":"h","min":0,"visible_when":"methode IN {''chlorung'', ''h2o2''}","aria_label":"Verweilzeit des Desinfektionsmittels im System"},{"key":"verweilzeit_ok","label":"Mindestverweilzeit","type":"derived","expr":"if(verweilzeit_h >= lookup(''TAB14'', methode, ''verweilzeit_min_h''), 1, 0)","display":"badge","value_labels":{"0":"unter der Mindestverweilzeit 12 h (Tab. 14)","1":"≥ 12 h (Tab. 14)"}},{"key":"temp_c","label":"Temperatur","type":"number","unit":"°C","min":0,"visible_when":"methode == ''thermisch''","aria_label":"Temperatur der thermischen Desinfektion"},{"key":"dauer_min","label":"Dauer","type":"number","unit":"min","min":0,"visible_when":"methode == ''thermisch''","aria_label":"Dauer der thermischen Desinfektion"},{"key":"thermisch_ok","label":"70 °C / 3 min","type":"derived","expr":"if(methode == ''thermisch'', if(temp_c >= 70 AND dauer_min >= 3, 1, 0), 1)","display":"badge","value_labels":{"0":"unter 70 °C über 3 min (§7.2.5)","1":""}},{"key":"dokumentiert","label":"dokumentiert","type":"boolean"}],"note":"Eine chemische Behandlung des aufbereiteten Wassers mit anderen als in Tabelle 14 genannten Mitteln wird nicht empfohlen."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'desinfektionen') AND w.code = 'M12003-22' AND s.code = 'DWA-M-1200-3';
