SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = '24-B'), 'expositionspfade', 'Expositionspfade je Bewässerungsfläche (Technik, Aufnahmepfad, Exposition nach Tab. 15, Maßnahme)', 'json', NULL, false, '§8, Tab. 15', 'Plan 3: Zeilen je Fläche × Aufnahmepfad (die sechs gedruckten Pfade L1812–L1818 als Vorschlagsliste; Expositionsgrad wie in Tab. 15 gedruckt — die Tab.-15-Zeilenköpfe sind Bilder, m1200_3-U-3, daher keine Tabelle); der Boolean expositionspfade_dokumentiert und CR-13 bleiben.', 'imported_unverified', 'direkte Aufnahme über Inhalation von Aerosolen
direkte Aufnahme über Ingestion von Tropfen
direkte Aufnahme über dermalen Kontakt
indirekte Aufnahme über Ingestion von Bodenpartikeln und Pflanzenbestandteilen
indirekte Aufnahme über dermalen Kontakt mit bewässertem Boden oder Pflanzen
![](https://cdn.mathpix.com/cropped/3e6ee836-6623-497f-81fd-e75e0ba9bf8b-57.jpg?height=76&width=118&top_left_y=1631&top_left_x=351)
indirekte Aufnahme: Nahrungsaufnahme von mit aufbereiteten Wasser bewässerten pflanzlichen Produkten — Die Relevanz der Expositionspfade ist neben der Nutzungsart bzw. Nutzungsgruppe vom jeweiligen Bewässerungssystem abhängig (Tabelle 15). — \caption{Tabelle 15: Relevante Expositionspfade bei der Bewässerung für Beschäftigte in Landwirtschaft, Gartenbau, GaLaBau und Wasserverteilung (Quelle: abgeändert nach DWA-Themenband Hygiene)}', 'register', '{"title":"Expositionspfade je Bewässerungsfläche (Tab. 15)","subtitle":"§8 — je Fläche Bewässerungstechnik, Aufnahmepfad (Liste §8), Expositionsgrad nach Tab. 15 und Maßnahme","add_label":"+ Expositionspfad","placement":"section","columns":[{"key":"flaeche","label":"Fläche / Schlag","type":"text","required":true},{"key":"technik","label":"Bewässerungstechnik","type":"enum","required":true,"options":["beregnung_sprinkler","tropfbewaesserung","mikrosprueh","hydroponik","einstau","furchenbewaesserung","rieselbewaesserung"],"option_labels":{"beregnung_sprinkler":"Beregnung (Sprinkler)","tropfbewaesserung":"Tropfbewässerung","mikrosprueh":"Mikrosprühsystem","hydroponik":"Hydroponik","einstau":"Einstaubewässerung","furchenbewaesserung":"Furchenbewässerung","rieselbewaesserung":"Rieselbewässerung"}},{"key":"pfad","label":"Aufnahmepfad","type":"text","required":true,"datalist":["direkte Aufnahme über Inhalation von Aerosolen","direkte Aufnahme über Ingestion von Tropfen","direkte Aufnahme über dermalen Kontakt","indirekte Aufnahme über Ingestion von Bodenpartikeln und Pflanzenbestandteilen","indirekte Aufnahme über dermalen Kontakt mit bewässertem Boden oder Pflanzen","indirekte Aufnahme: Nahrungsaufnahme von mit aufbereiteten Wasser bewässerten pflanzlichen Produkten"]},{"key":"exposition","label":"Exposition (Tab. 15)","type":"enum","required":true,"options":["nicht_vorhanden","nicht_vorhanden_bis_gering","gering_bis_mittel","mittel_bis_hoch"],"option_labels":{"nicht_vorhanden":"Nicht vorhanden","nicht_vorhanden_bis_gering":"Nicht vorhanden bis gering","gering_bis_mittel":"Gering bis mittel","mittel_bis_hoch":"Mittel bis hoch"}},{"key":"massnahme","label":"Maßnahme (Arbeitsschutz)","type":"text"}],"note":"Die Relevanz der Expositionspfade ist neben der Nutzungsart bzw. Nutzungsgruppe vom jeweiligen Bewässerungssystem abhängig (Tabelle 15)."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'expositionspfade') AND w.code = 'M12003-24' AND s.code = 'DWA-M-1200-3';
